def round_half_to_even(n):
    # If the number is not a number (NaN), a infinity, or a negative infinity, return it as is
    # because these are not valid inputs for the round() function
    if not isinstance(n, float) or math.isnan(n) or math.isinf(n):
        return n

    # Convert the number to a string and split it into its integer and decimal parts
    str_n = str(n)
    parts = str_n.split('.')

    # If the number has no decimal part, return it as is
    if len(parts) == 1:
        return n

    # If the number has a decimal part, check if it is >= 0.5
    # If it is >= 0.5, round up to the nearest integer
    # If it is < 0.5, round down to the nearest integer
    # If the number is odd, round up if the last digit is >= 5
    # If the number is even, round up if the last digit is >= 6
    if parts[1] >= '5':
        return int(parts[0]) + 1
    else:
        return int(parts[0])

