def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Arguments:
        name (str): The name of the new subclass.
        fields (list[function]): A list of functions to use for the validator.
        srid_map (dict): A dictionary of SRID mapping functions.

    Returns:
        A new subclass of Point.

    """

    def validate(self):
        if not issubclass(self.__class__, Point):
            raise ValueError("The class is not a Point class.")
        if not self.validator(self):
            raise ValueError("The point is not valid.")

    def validate_srid(self):
        if not self.geometry.srid in self.srid_map:
            raise ValueError("The srid is not valid.")
        if not self.validator(self):
            raise ValueError("The point is not valid.")

    def validate_srid(self):
        if not self.validator(self):
            raise ValueError("The point is not valid.")

    return type(name, (Point,), {"validator": validate, "validate_srid": validate_srid})

