def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    cmd = ['R', '--quiet', '--no-restore', '--no-save', '--slave']
    for option in ['--no-readline', '--no-save', '--no-restore']:
        if option in env:
            cmd.append(option)
    if 'R_QUIET' in env:
        cmd.append('--quiet')
    if 'R_SLAVE' in env:
        cmd.append('--slave')
    return ' '.join(cmd)
