def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """

    if len(cmd) + len(varargs) <= _max_length:
        cmd = (*cmd, *varargs, *kwargs.values())
        return _call_pty(cmd, color=color, target_concurrency=target_concurrency)
    else:
        partitions = []
        for vararg in varargs:
            partitions.append((*cmd, vararg, *kwargs.values()))
            if len(partitions) >= target_concurrency:
                partition_pool = multiprocessing.Pool(target_concurrency)
                results = partition_pool.map(partition_func, partitions, chunksize=1)
                partition_pool.terminate()
                results = [result for result in results if result]
                if not results:
                    raise RuntimeError("Error running xargs")
                else:
                    return results

