def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if len(cmd) > 0:
        cmd = (cmd[0],) + tuple(cmd[1:])
    if sys.platform == "win32":
        # Strip off quotes, but only if they weren't needed
        match = re.match(r'^(.+?)(#.*|"$)', cmd[0])
        if match:
            cmd = (match.group(1),) + tuple(cmd[1:])
    return cmd

