def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
    # remove the class "object" from the list, as it is a built-in class in python
    if object in bases:
        bases.remove(object)
    return bases

