def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    Arguments:
        separator (str): Delimits values, defaults to ",".
        header (Any): If not ``None``, is the first string of the output.

    Returns:
        str: CSV string of the graph's points.
    """
    if header is not None:
        header = str(header)
        output_rows = [header + "\n"]
    else:
        output_rows = []

    for point in self.points:
        output_rows.append(",".join(str(coord) for coord in point))

    return "\n".join(output_rows)

