    if not isinstance(inventory, Inventory):
        raise TypeError("Inventory must be of type Inventory")

    # If extract_spec_version is True, check the type value to determine the specification version
    if extract_spec_version and 'type' in inventory.attributes and inventory.attributes['type'] in VALID_INVENTORY_TYPES:
        self.spec_version = INVENTORY_TYPES[inventory.attributes['type']]
    else:
