def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url

    pattern = re.compile(r'\[([A-Za-z0-9_]+)]')
    match = pattern.search(url)

    while match:
        arg = match.group()[1:-1]
        if arg not in url_args:
            raise KeyError('Missing value for URL argument ' + arg)

        url = url.replace(match.group(), url_args[arg])
        match = pattern.search(url)

    return url

