def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Return information about the loaded configurations.

    Args:
        config_filenames (list of str): File names of the configuration files to load.
        overrides (dict, optional): Override values for the configuration. Defaults to None.
        resolve_env (bool, optional): Whether to resolve environment variables in the configuration. Defaults to True.

    Returns:
        dict: Dictionary of configuration filename to corresponding parsed configuration
        list: Sequence of logging.LogRecord instances containing any parse errors
    """
    configurations = {}
    records = []
    for config_filename in config_filenames:
        try:
            with open(config_filename, "r") as f:
                configuration = json.load(f)
        except FileNotFoundError:  # pragma: no cover  # pylint: disable=bare-except
            records.append(logging.LogRecord("", logging.WARNING, "", 0, "Configuration file %s not found.", config_filename))
            continue
        except json.JSONDecodeError as e:  # pragma: no cover  # pylint: disable=bared-except
            records.append(logging.LogRecord("", logging.ERROR, "", 0, "Invalid JSON in configuration file %s.", config_filename))
            continue
        configurations[config_filename] = configuration
    if overrides:
        for config_filename, configuration in configurations.items():
            for key, value in overrides.items():
                try:
                    field = configuration[key]  # pylint: disable=unsubscriptable-object
                except KeyError:
                    records.append(logging.LogRecord("", logging.WARNING, "", 0, "Override value for unknown key %s in configuration file %s.", key, config_filename))
                else:
                    try:
                        field.update_value(value, resolve_env)
                    except ValueError:
                        records.append(logging.LogRecord("", logging.ERROR, "", 0, "Failed to update value %s for key %s in configuration file %s.", value, key, config_filename))

    return configurations, records

