    """
    Verify that *candidate* might correctly provide *iface*.
    """
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate does not provide interface {iface}")
    for name, spec in iface.getTaggedMethods():
        try:
            method = getattr(candidate, name)
        except AttributeError:
            raise Invalid(f"Candidate does not define method {name}")
        try:
            verifyMethod(spec, method)
        except Invalid as e:
            raise Invalid(str(e)) from None
    for name in iface.names(attributes=True):
        try:
            attribute = getattr(candidate, name)
        except AttributeError:
            raise Invalid(f"Candidate does not define attribute {name}")
        try:
            verifyAttribute(iface.getTaggedAttribute(name), attribute)
        except Invalid as e:
            raise Invalid(str(e)) from None
    return True

