def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get("https://link-discovery. verschiedenen-kram.net/webfinger?resource=acct:" + handle, headers={"Accept": "application/json"}, timeout=20)
    except requests.exceptions.ConnectTimeout:
        return None # provide a helpful error message

    if response.status_code == 200:
        body = response.json()
        if body and "links" in body and len(body["links"]) > 0:
            #check if there is a link with rel="http://webfinger.net/rel/profile-page"
            link_object = None
            for link in body["links"]:
                if "rel" in link and link["rel"] == "http://webfinger.net/rel/profile-page":
                    link_object = link
                    break
            if link_object is None:
                # if there is no link with rel="http://webfinger.net/rel/profile-page", return the link with rel="self"
                for link in body["links"]:
                    if "rel" in link and link["rel"] == "self":
                        link_object = link
                        break
            if link_object is not None and "href" in link_object:
                return link_object["href"]
            else:
                return None
        else:
            return None
    else:
        return None

